def hydrate_time(nanoseconds, tz):
    seconds, nsecs = divmod(nanoseconds, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    time_components = map(int, [hours, minutes, seconds, nsecs // 1000])
    time_obj = datetime.time(*time_components)
    if tz is not None:
        time_obj = tz.localize(time_obj)
    return Time(time_obj)

